#!/usr/bin/env python3
"""Writes runtime_js.h: runtime.js as a NUL-terminated C array (QuickJS needs the NUL)."""
import pathlib, sys

here = pathlib.Path(__file__).parent
src = (here / "runtime.js").read_bytes()
lines = []
for i in range(0, len(src), 16):
    lines.append("    " + ", ".join(f"0x{b:02x}" for b in src[i:i + 16]) + ",")
out = (
    "// Generated by gen_runtime.py from runtime.js: do not edit.\n"
    "static const unsigned char honk_card_runtime_js[] = {\n"
    + "\n".join(lines)
    + "\n    0x00\n};\n"
    f"static const unsigned int honk_card_runtime_js_len = {len(src)};\n"
)
target = here / "runtime_js.h"
if "--check" in sys.argv:
    if not target.exists() or target.read_text() != out:
        sys.exit("runtime_js.h is out of date: run `make -C native runtime`")
else:
    target.write_text(out)
